INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (1, 1, 0, 1, 1, 'a:0:{}', NULL, NULL, '<p>Robbi zidni &lsquo;ilma warzuqni fahma. Doa tersebut kita ucapkan pada saat&hellip;</p>\n', '<p>Sebelum makan     </p>\n', '<p>Sebelum tidur</p>\n', '<p>Memulai belajar</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'C', 1730408450, 1730408450, 1, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (2, 1, 0, 1, 2, 'a:0:{}', NULL, NULL, '<p>Dalam belajar, selain berniat hanya kepada Allah dan rajin kita juga harus&hellip;</p>\n', '<p>Bersungguh-sungguh  </p>\n', '<p>Belajar disekolah saja   </p>\n', '<p>Belajar bila disuruh</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'A', 1730408450, 1730408450, 1, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (3, 1, 0, 1, 3, 'a:0:{}', NULL, NULL, '<p>Seusai belajar, sebaiknya kita mengucapkan hamdalah yang berbunyi…</p>\r\n', '<p>Allahuakbar     </p>\r\n', '<p>Alhamdulillahirobbil’alamin    </p>\r\n', '<p>Subhanallah</p>\r\n', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'b', 1730408450, 1731334087, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (4, 1, 0, 1, 4, 'a:0:{}', NULL, NULL, '<p>Sebelum membaca Al-Quran, kita sebaiknya&hellip;</p>\n', '<p>Sarapan</p>\n', '<p>Berwudhu</p>\n', '<p>Berolahraga</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'B', 1730408450, 1730408450, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (5, 1, 0, 1, 5, 'a:0:{}', NULL, NULL, '<p>Surah Al-Ikhlas terdiri atas berapa ayat?</p>\n', '<p>2 Ayat</p>\n', '<p>3 Ayat </p>\n', '<p>4 Ayat</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'C', 1730408450, 1730408450, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (6, 1, 0, 1, 6, 'a:0:{}', NULL, NULL, '<p>Surah Al-Ikhlas bercerita tentang keesaan Allah. Allah itu esa, maksudnya adalah&hellip;</p>\n', '<p>Allah itu Satu  </p>\n', '<p>Allah itu Maha Penyayang  </p>\n', '<p>Allah itu Maha Merajai</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'A', 1730408450, 1730408450, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (7, 1, 0, 1, 7, 'a:0:{}', NULL, NULL, '<p>Anak yang durhaka kepada Ayah dan Ibu akan masuk&hellip;</p>\n', '<p>Neraka </p>\n', '<p>Syurga </p>\n', '<p>Penjara</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'A', 1730408450, 1730408450, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (8, 1, 0, 1, 8, 'a:0:{}', NULL, NULL, '<p>Allah itu tidak dilahirkan davn tidak pula&hellip;</p>\n', '<p>Memberikan </p>\n', '<p>Melahirkan </p>\n', '<p>Memaafkan</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'B', 1730408450, 1730408450, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (9, 1, 0, 1, 9, 'a:0:{}', NULL, NULL, '<p>Allah adalah Tuhan tempat manusia&hellip;</p>\n', '<p>Menolak </p>\n', '<p>Meminta </p>\n', '<p>Memeriksa</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'B', 1730408450, 1730408450, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (10, 1, 0, 1, 10, 'a:0:{}', NULL, NULL, '<p>Menghilangkan najis disebut&hellip;</p>\n', '<p>Karomah </p>\n', '<p>Thoharoh </p>\n', '<p>Barokah</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'B', 1730408450, 1730408450, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (11, 1, 0, 1, 11, 'a:0:{}', NULL, NULL, '<p>Shalat fardu atau shalat wajib terdiri atas berapa waktu&hellip;</p>\n', '<p>3 Waktu </p>\n', '<p>4 Waktu</p>\n', '<p>5 Waktu</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'C', 1730408450, 1730408450, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (12, 1, 0, 1, 12, 'a:0:{}', NULL, NULL, '<p>Alat bersuci yang paling sempurna adalah&hellip;</p>\n', '<p>Batu </p>\n', '<p>Air </p>\n', '<p>Tisu</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'B', 1730408450, 1730408450, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (13, 1, 0, 1, 13, 'a:0:{}', NULL, NULL, '<p>Manusia pertama kali yang diciptakan Allah adalah&hellip;</p>\n', '<p>Nabi adam</p>\n', '<p>Nabi yusuf </p>\n', '<p>Nabi Isa</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'A', 1730408450, 1730408450, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (14, 1, 0, 1, 14, 'a:0:{}', NULL, NULL, '<p> Istri Nabi Adam Bernama&hellip;</p>\n', '<p>Fatimah </p>\n', '<p>Aisyah </p>\n', '<p>Hawa</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'C', 1730408450, 1730408450, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (15, 1, 0, 1, 15, 'a:0:{}', NULL, NULL, '<p>Nabi Nuh dan pengikutnya akhirya selamat setelah naik&hellip;.</p>\n', '<p>Pesawat </p>\n', '<p>B Kapal </p>\n', '<p>Mobil</p>\n', '', '', NULL, NULL, NULL, NULL, NULL, 'B', 1730408450, 1730408450, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (16, 2, 0, 1, 1, 'a:0:{}', NULL, NULL, '<p>Yang dapat mempersatukan orang percaya dalam satu persekutuan yang bersaksi tentang Kristus adalah....</p>\n', '<p>lidah-lidah api</p>\n', '<p>bahasa pemersatu</p>\n', '<p>Roh kudus</p>\n', '<p>adanya kepentingan bersama</p>\n', '<p>pengajaran para rasul</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 1, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (17, 2, 0, 1, 2, 'a:0:{}', NULL, NULL, '<p>Hari ketika turunnya lidah- lidah api ke atas para murid dan membuat mereka dapat bersaksi tentang Kristus sekaligus merupakan cikal bakal berdirinya jemaat mula-mula di rayakan dengan hari raya....</p>\n', '<p>Pantekosta</p>\n', '<p>pondok daun</p>\n', '<p>persatuan</p>\n', '<p>pentakosta</p>\n', '<p>perdamaian</p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1730408507, 1730408507, 1, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (18, 2, 0, 1, 3, 'a:0:{}', NULL, NULL, '<p>Untuk menyatakan tanggungjawabnya menolong orang percaya, Roh Kudus disebut sebagai....</p>\n', '<p>pentakosta</p>\n', '<p>roh Allah</p>\n', '<p>parakletos</p>\n', '<p>pemberi karunia</p>\n', '<p>pemersatu jemaat</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 1, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (19, 2, 0, 1, 4, 'a:0:{}', NULL, NULL, '<p>Roh membantu kita dalam kelemahan kita dan berdoa untuk kita kepada Allah. Ia adalah....</p>\n', '<p>penolong yang lain</p>\n', '<p>pendoa syafaat</p>\n', '<p>pemberi karunia</p>\n', '<p>pemersatu jemaat</p>\n', '<p>penghibur sejati</p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1730408507, 1730408507, 1, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (20, 2, 0, 1, 5, 'a:0:{}', NULL, NULL, '<p>Petrus tidak saja mengajarkan Firman Allah kepada jemaat dan orang banyak, tetapi juga menerima karunia untuk....</p>\n', '<p>memimpin</p>\n', '<p>membabtis</p>\n', '<p>berbahasa Roh</p>\n', '<p>menadakan mujizat</p>\n', '<p>mendapat penglihatan</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 1, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (21, 2, 0, 1, 6, 'a:0:{}', NULL, NULL, '<p>Manusia berdosa dalam segala usahanya, tetapi ingin melepaskan diri dari dosa,sebab,ia telah dibutakan oleh iblis untuk melihat....</p>\n', '<p>kebaikan</p>\n', '<p>kewajiban</p>\n', '<p>kebenaran</p>\n', '<p>keindahan</p>\n', '<p>kerukunan</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (22, 2, 0, 1, 7, 'a:0:{}', NULL, NULL, '<p>Roh Kudus turun ke atas Petrus sehingga ia dapat melakukan apa yang belum pernah di lakukannya yaitu....</p>\n', '<p>mendapat banyak ikan</p>\n', '<p>mengajak banyak orang</p>\n', '<p>menyangkal Yesus tiga kali</p>\n', '<p>memimpin murid- murid lain</p>\n', '<p>berkotbah di depan orang banyak</p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (23, 2, 0, 1, 8, 'a:0:{}', NULL, NULL, '<p>Ketika Paulus bertemu dengan Tuhan Yesus dalam perjalanan ke Damsyik, Roh Kudus menyadarkan Paulus bahwa yang di lakukan selama ini adalah....</p>\n', '<p>menganiaya pengikut jalan Tuhan</p>\n', '<p>memenuhi keinginan mahkamah Agama</p>\n', '<p>menganiaya Tuhan Yesus</p>\n', '<p>mematuhi hukum taurat</p>\n', '<p>membenci orang Yahudi</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (24, 2, 0, 1, 9, 'a:0:{}', NULL, NULL, '<p>Saat kita berdiri di hadapan Allah dalam pengadilan kelak, yang akan berdiri sebagai saksi atas hidup kita adalah....</p>\n', '<p>orang tua kita</p>\n', '<p>orang terdekat kita</p>\n', '<p>roh kebenaran</p>\n', '<p>malaikat pencatat kehidupan</p>\n', '<p>buku kehidupan kita</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (25, 2, 0, 1, 10, 'a:0:{}', NULL, NULL, '<p>Dalam kitab Roma dan Galatia, Paulus berbicara tentang kemerdekaan dari dosa. Tak seorangpun manusia dapat memperoleh keselamatan kekal tanpa melalui Yesus.Untuk di selamatkan Yesus, manusia harus memiliki....</p>\n', '<p>perbuatan baik</p>\n', '<p>upah kebaikan</p>\n', '<p>iman kepada Yesus</p>\n', '<p>persembahan perdamaian</p>\n', '<p>kehidupan yang suci</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (26, 2, 0, 1, 11, 'a:0:{}', NULL, NULL, '<p>Paulus harus bersyukur atas kasih keselamatan oleh Kristus yang dialaminya . Meskipun demikian tidak semua penderitaannya di angkat oleh Tuhan. Sebab itu selama hidupnya Paulus tetap memikul salib oleh karena....</p>\n', '<p>akibat pelayanannya</p>\n', '<p>duri di dalam daging</p>\n', '<p>hambatan orang Roma</p>\n', '<p>kerasulannya diragukan</p>\n', '<p>tidak cocok dengan Petrus</p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (27, 2, 0, 1, 12, 'a:0:{}', NULL, NULL, '<p>Tabir bait suci terbela dua dari atas hingga ke bawah, ketika Tuhan Yesus menyerahkan nyawaNya di atas kayu salib. Tabir ini memisahkan ruang maha kudus dan kudus. Tabir yang terbela ini melambangkan....</p>\n', '<p>ada seorang pembuka jalan</p>\n', '<p>jalan damai telah terbuka</p>\n', '<p>Yesus memasuki ruang kudus</p>\n', '<p>siapapun bisa datang kepada Allah</p>\n', '<p>bait suci di kuduskan kembali</p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (28, 2, 0, 1, 13, 'a:0:{}', NULL, NULL, '<p>Pemilihan Allah atas orang percaya di dasarkan pemilihan di dalam dan melalui Yesus Kristus. Konsekuensinya adalah....</p>\n', '<p>hidup dengan etika Gereja</p>\n', '<p>hidup serupa dengan Kristus</p>\n', '<p>memberitakan firman Allah</p>\n', '<p>melayani untuk orang miskin</p>\n', '<p>menjadi teladan untuk sesama</p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (29, 2, 0, 1, 14, 'a:0:{}', NULL, NULL, '<p>Paulus menyerahkan seluruh hidupnya untuk melayani Kristus, yang telah menebus semua dosanya. Penyerahan diri ini dapat di pahami melalui kalimatnya yaitu....</p>\n', '<p>&ldquo;bukan kehendakKu melainkan kehendakMu yangjadi&rdquo;</p>\n', '<p>&ldquo; Segala perkara dapat kutanggung di dalam Dia &ldquo;</p>\n', '<p>&ldquo; Serigala memilliki liang dan burung memilliki sarang&rdquo;</p>\n', '<p>&ldquo;kamulah bangsa yang terpilih imamat yang rajani&rdquo;</p>\n', '<p>&ldquo;hidup adalah bagi Kristus dan mati adalah untung&rdquo;</p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (30, 2, 0, 1, 15, 'a:0:{}', NULL, NULL, '<p>Dalam realita hidup, kawan bisa berubah menjadi lawan ; dan sahabat bisa berubah menjadi penghianat. Dalam situasi tersebut, remaja Kristen harus bersikap....</p>\n', '<p>penuh curiga pada orang lain</p>\n', '<p>mawas diri terhadap siapa saja</p>\n', '<p>tidak percaya kepada orng lain</p>\n', '<p>kejahatan dibalas kejahatan setimpal</p>\n', '<p>peka terhadap berbagai bentuk kejahatan</p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (31, 2, 0, 1, 16, 'a:0:{}', NULL, NULL, '<p>Melalui sepuluh hukum dalam Keluaran 20:1-17, Allah hendak membarui bangsa Israel melalui....</p>\n', '<p>hidup secara teratur</p>\n', '<p>pola hidup yang kudus</p>\n', '<p>cara hidup seperti Allah</p>\n', '<p>hidup harus selalu baik</p>\n', '<p>hidup sesuai adat Yahudi</p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (32, 2, 0, 1, 17, 'a:0:{}', NULL, NULL, '<p>Kematian dan kebangkitan Tuhan Yesus membuktikan bahwa dalam karya pembaruanNya Allah memberikan jaminan atas....</p>\n', '<p>berkat Tuhan atas kehidupan</p>\n', '<p>pemulihan hubungan manusia</p>\n', '<p>umur manusia akan panjang</p>\n', '<p>kehidupan kekal bagi manusia</p>\n', '<p>kematian kekal bagi manusia</p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (33, 2, 0, 1, 18, 'a:0:{}', NULL, NULL, '<p>Akar yang baik akan menyerap mineral yang cukup untuk pertumbuhan pohon Orang Kristen akan mempunyai kemampuan menyerap kebenaran firman Tuhan bagi pertumbuhan rohaninya apabila....</p>\n', '<p>ia di tanam di tepi aliran sungai</p>\n', '<p>tidak ada hama yang mengganggu</p>\n', '<p>bertahan menghadapi berbagai pencobaan</p>\n', '<p>tinggal diam tidak merespon masalah</p>\n', '<p>mempunyai banyak pengalaman hidup</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (34, 2, 0, 1, 19, 'a:0:{}', NULL, NULL, '<p>Bahasa Junani yang di gunakan untuk menggambarkan pengudusan orang percaya oleh Roh kudus adalah....</p>\n', '<p>huiothesia</p>\n', '<p>hagiasmos</p>\n', '<p>illumination</p>\n', '<p>parakletos</p>\n', '<p>hupotasso</p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (35, 2, 0, 1, 20, 'a:0:{}', NULL, NULL, '<p>Jalan pembuka bagi proses pengudusan hidup bagi orang kristen dan jembatan yang menghubungkan sehingga ada persekutuan antara orang kristen dan Allah serta olehnya manusia di benarkan oleh karena....</p>\n', '<p>iman</p>\n', '<p>pengudusn</p>\n', '<p>pengangkatan</p>\n', '<p>pertumbuhan</p>\n', '<p>pembebasan</p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (36, 2, 0, 1, 21, 'a:0:{}', NULL, NULL, '<p>Dalam kitab Galatia, paulus menjelaskan pertumbuhan rohani orang percaya dengan menggunakan illustrasi....</p>\n', '<p>peternakan</p>\n', '<p>kemerdekaan</p>\n', '<p>metamorposa</p>\n', '<p>pemberian hadiah</p>\n', '<p>pertanian</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (37, 2, 0, 1, 22, 'a:0:{}', NULL, NULL, '<p>Proses yang terus berjalan seumur hidup orang percaya melalui mempelajari dan menerapkan kebenaran untuk semakin serupa dengan kristus adalah....</p>\n', '<p>pengudusan</p>\n', '<p>pengangkatan</p>\n', '<p>pembebasaan</p>\n', '<p>pertumbuhan</p>\n', '<p>pemberi pengertian</p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (38, 2, 0, 1, 23, 'a:0:{}', NULL, NULL, '<p>Roh Kudus mempersekutukan orang- orang percaya dalam jemaat mula-mula sehingga setiap hari mereka berkumpul untuk mendengarka ajaran para rasul. ini adalah pekerjaan Roh Kudus, yaitu....</p>\n', '<p>mempersekutukan</p>\n', '<p>menyatukan</p>\n', '<p>memberi karunia</p>\n', '<p>memberi pertumbuhan</p>\n', '<p>menguduskan orang berdosa</p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (39, 2, 0, 1, 24, 'a:0:{}', NULL, NULL, '<p>Karena pertolongan Roh Kudus, maka kita dapat memanggil Allah sebagai....</p>\n', '<p>tuan</p>\n', '<p>raja</p>\n', '<p>bapa</p>\n', '<p>hakim</p>\n', '<p>yang mulia</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (40, 2, 0, 1, 25, 'a:0:{}', NULL, NULL, '<p>Yang dapat mempersatukan orang percaya dalam satu persekutuan untuk bersaksi tentang Kristus adalah....</p>\n', '<p>lidah- lidah api</p>\n', '<p>bahasa pemersatu</p>\n', '<p>kepentingan bersama</p>\n', '<p>Roh kudus</p>\n', '<p>pengajaran para rasul</p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (41, 2, 0, 1, 26, 'a:0:{}', NULL, NULL, '<p>Ia pernah mengalami penganiayaan namun ia juga menyembunyikan orang-orang Yahudi lainnya dari penganiayaan, Tokoh yang dimaksud adalah....</p>\n', '<p>Ludwig van beethoven</p>\n', '<p>Hudson Tailor</p>\n', '<p>Stepanus</p>\n', '<p>Ananias</p>\n', '<p>Corrie Ten Boom</p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (42, 2, 0, 1, 27, 'a:0:{}', NULL, NULL, '<p>Dari jerih payahnya melayani sebagai missionaris, berdirilah CIM yang saat ini bernama OMF, tokoh yang dimaksudkan adalah...</p>\n', '<p>Hudson Taylor</p>\n', '<p>Akwila dan Priskila</p>\n', '<p>Paulus</p>\n', '<p>Barnabas</p>\n', '<p>Coorie Ten Boom</p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (43, 2, 0, 1, 28, 'a:0:{}', NULL, NULL, '<p>Saat kita berdiri di hadapan Allah dalam pengadilan kelak, yang akan berdiri sebagai saksi atas hidup kita adalah....</p>\n', '<p>orangtua kita</p>\n', '<p>orang terdekat kita</p>\n', '<p>roh kebenaran</p>\n', '<p>malaikat pencatat kehidupan</p>\n', '<p>buku kehidupan kita</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (44, 2, 0, 1, 29, 'a:0:{}', NULL, NULL, '<p>Paulus menekankan betapa pentingnya kasih bagi orang percaya Meskipun seseorang mempunyai berbagai karunia , tetapi ia tidak memiliki kasih ia akan sama dengan....</p>\n', '<p>jemaat mula- mula</p>\n', '<p>orang- orang di luar Kristus</p>\n', '<p>orang yang tidak percaya</p>\n', '<p>para rasul Kristus</p>\n', '<p>gong yang berkumandang</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (45, 2, 0, 1, 30, 'a:0:{}', NULL, NULL, '<p>Petrus daapat mengajar, Paulus memberitakan injil, Yohanes menjadi soko guru, Priskila dan Akwila memperhatikan pelayanan. Semua bagian dalam pelayanan jemaat di kerjakan oleh....</p>\n', '<p>orang percaya</p>\n', '<p>kuasa Roh kudus</p>\n', '<p>semua jemaat</p>\n', '<p>karunia Roh Kudus</p>\n', '<p>persekutuan tubuh Kristus</p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (46, 2, 0, 1, 31, 'a:0:{}', NULL, NULL, '<p>Murid- murid berdukacita karena Tuhan Yesus akan meninggalkan mereka untuk kembali ke surga Tuhan Yesus tau kebutuhan mereka . Oleh karena itu ia mengutus....</p>\n', '<p>penolong lain yaitu Roh Kudus</p>\n', '<p>Rasul Paulus</p>\n', '<p>Priskila dan Akwila</p>\n', '<p>Gamaliel ahli taurat</p>\n', '<p>Malaikat Gabriel</p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (47, 2, 0, 1, 32, 'a:0:{}', NULL, NULL, '<p>Allah dapat menggunakan setiap peristiwa untuk membimbing manusia kedalam pembebasan dengan pertolongan Roh Kudus. Martin Luther mengalami pembaruan oleh Roh Kudus, yaitu....</p>\n', '<p>memulai kaulnya</p>\n', '<p>menjadi biarawan</p>\n', '<p>menyetujui indulgensia</p>\n', '<p>membaca Alkitab</p>\n', '<p>percaya firman Allah</p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (48, 2, 0, 1, 33, 'a:0:{}', NULL, NULL, '<p>Pertumbuhan rohani yang dialami oleh Martin Luther membawanya pada pemahaman bahwa ....</p>\n', '<p>gereja di dunia sudah sesat</p>\n', '<p>orang lemah oleh dosa</p>\n', '<p>tokoh gereja berkuasa di dunia</p>\n', '<p>keselamatan adalah usaha manusia</p>\n', '<p>Alkitab satu-satunya sumber kebenaran</p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (49, 2, 0, 1, 34, 'a:0:{}', NULL, NULL, '<p>Manusia selalu membutuhkan orang lain meskipun dalam kehidupan bersama biasanya ada perselisihan yang terjadi. Hal ini menunjukkan bahwa manusia diciptakan sebagai....</p>\n', '<p>mahluk mulia</p>\n', '<p>mahluk sosial</p>\n', '<p>mahluk pribadi</p>\n', '<p>mahluk sempurna</p>\n', '<p>mahluk yang unik</p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (50, 2, 0, 1, 35, 'a:0:{}', NULL, NULL, '<p>Identitas orang percaya sebagai garam dunia tampak dalam hidup yang memberikanpengaruh kepada orang lain. Sedangkan sebagai terang dunia,orang percaya menjadi....</p>\n', '<p>teladan</p>\n', '<p>pemimpin</p>\n', '<p>penerang hati</p>\n', '<p>yang terpandang</p>\n', '<p>pusat kehidupan</p>\n', NULL, NULL, NULL, NULL, NULL, 'A', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (51, 2, 0, 1, 36, 'a:0:{}', NULL, NULL, '<p>Memperbarui watak manusia yang telah menyerahkan diri kepada Kristus dan menuntun kepada tindakan yang sesuai dengan kebenaran, adalah pekerjaan Roh Kudus dalam hidup orang percaya yaitu....</p>\n', '<p>pengangkatan</p>\n', '<p>pengudusan</p>\n', '<p>pemberi pertumbuhan</p>\n', '<p>pemberi anugrah</p>\n', '<p>pembebasan</p>\n', NULL, NULL, NULL, NULL, NULL, 'B', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (52, 2, 0, 1, 37, 'a:0:{}', NULL, NULL, '<p>Dalam kepelbagaian Roh Kudus mempersatukan orang percaya di seluruh dunia menjadi....</p>\n', '<p>satu kepala gereja</p>\n', '<p>satu kasih</p>\n', '<p>satu tubuh Kristus</p>\n', '<p>satu gereja</p>\n', '<p>satu dalam tubuh Kristus</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (53, 2, 0, 1, 38, 'a:0:{}', NULL, NULL, '<p>Ananias dan Sapira di hukum mati oleh Tuhan karena mereka mendustai Roh Kudus. Petrus menegur mereka karena Roh Kudus menolong Petrus untuk....</p>\n', '<p>menghakimi dan menghukum</p>\n', '<p>membedakan mana yang salah dan benar</p>\n', '<p>menegur kesalahan agar bertobat</p>\n', '<p>membiarkan mereka di hukum mati</p>\n', '<p>menjadi pemimpin yang otoriter</p>\n', NULL, NULL, NULL, NULL, NULL, 'C', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (54, 2, 0, 1, 39, 'a:0:{}', NULL, NULL, '<p>Sejak kejatuhan manusia kedalam dosa, tidak seorangpun yang mampu melawn iblis. Yang harus di lakukan agar tidak jatuh kedalam dosa adalah....</p>\n', '<p>rajin berdoa dan puasa</p>\n', '<p>rajin membaca Alkitab</p>\n', '<p>rajin mengikuti ibadah</p>\n', '<p>meneguhkan diri agar kuat</p>\n', '<p>menyerahkan diri pada Roh Kudus</p>\n', NULL, NULL, NULL, NULL, NULL, 'E', 1730408507, 1730408507, 0, '', 8, 0, 0);
INSERT INTO `cbt_soal` (`id_soal`, `bank_id`, `mapel_id`, `jenis`, `nomor_soal`, `file`, `file1`, `tipe_file`, `soal`, `opsi_a`, `opsi_b`, `opsi_c`, `opsi_d`, `opsi_e`, `file_a`, `file_b`, `file_c`, `file_d`, `file_e`, `jawaban`, `created_on`, `updated_on`, `tampilkan`, `deskripsi`, `kesulitan`, `timer`, `timer_menit`) VALUES (55, 2, 0, 1, 40, 'a:0:{}', NULL, NULL, '<p>Kalimat yang benar menurut Alkitab tentang hubungan manusia berdosa dengan Roh Kudus adalah....</p>\n', '<p>manusia berdosa dikuasai Roh Kudus</p>\n', '<p>manusia berdosa tidak membutuhkan Roh Kudus</p>\n', '<p>Roh Kudus tidak mengasihi manusia berdosa</p>\n', '<p>Roh Kudus menuntun orang berdosa pada kebenaran</p>\n', '<p>manusia berdosa berada dalam kuasa Roh Kudus</p>\n', NULL, NULL, NULL, NULL, NULL, 'D', 1730408507, 1730408507, 0, '', 8, 0, 0);
